"""One-shot implementation patch for issue #23."""
from __future__ import annotations

import importlib
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

def write(path: str, content: str) -> None:
    target = ROOT / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding='utf-8')

write('src/csd_foundry/synthesis/v0_4/publication_protocol.py', '"""Topology-independent completion envelopes and append-only publication evidence."""\n\nfrom __future__ import annotations\n\nimport re\nfrom dataclasses import dataclass\nfrom enum import StrEnum\n\nfrom csd_foundry.synthesis.v0_4.attempts import AttemptAccepted, AttemptRejected\nfrom csd_foundry.synthesis.v0_4.choice_paths import AttemptKey, SampleKey\nfrom csd_foundry.synthesis.v0_4.execution_protocol import (\n    ATTEMPT_COMPLETION_ENVELOPE_SCHEMA_VERSION,\n    INVENTORY_COMPLETION_REFERENCE_SCHEMA_VERSION,\n    OPERATIONAL_PUBLICATION_SCHEMA_VERSION,\n    ExecutionInventory,\n    SampleExecutionSpec,\n)\nfrom csd_foundry.synthesis.v0_4.serialization import canonical_json_bytes, canonical_sha256\n\n_HEX_256_PATTERN = re.compile(r"^[0-9a-f]{64}$")\n_TOKEN_PATTERN = re.compile(r"^[a-z0-9][a-z0-9._-]*$")\n_UINT32_MAX = (1 << 32) - 1\n\n\nclass PublicationProtocolError(ValueError):\n    """Raised when publication evidence violates the v0.4 contract."""\n\n\nclass CompletionStatus(StrEnum):\n    ACCEPTED = "accepted"\n    REJECTED = "rejected"\n\n\nclass PublicationObjectKind(StrEnum):\n    ATTEMPT_COMPLETION_ENVELOPE = "attempt-completion-envelope"\n    INVENTORY_COMPLETION_REFERENCE = "inventory-completion-reference"\n\n\nclass PublicationDisposition(StrEnum):\n    PUBLISHED = "published"\n    EXISTING_IDENTICAL = "existing-identical"\n\n\ndef _require_digest(value: object, field_name: str) -> str:\n    if type(value) is not str or _HEX_256_PATTERN.fullmatch(value) is None:\n        raise PublicationProtocolError(f"{field_name} must be a lowercase SHA-256 digest")\n    return value\n\n\ndef _require_token(value: object, field_name: str) -> str:\n    if type(value) is not str or _TOKEN_PATTERN.fullmatch(value) is None:\n        raise PublicationProtocolError(f"{field_name} must be a lowercase ASCII token")\n    return value\n\n\ndef _sample_key_value(sample_key: SampleKey) -> dict[str, object]:\n    if type(sample_key) is not SampleKey:\n        raise PublicationProtocolError("sample_key must use the exact SampleKey class")\n    return {\n        "release": sample_key.release,\n        "sample_index": sample_key.sample_index,\n        "target_id": sample_key.target_id,\n    }\n\n\ndef _attempt_key_value(attempt_key: AttemptKey) -> dict[str, object]:\n    if type(attempt_key) is not AttemptKey:\n        raise PublicationProtocolError("attempt_key must use the exact AttemptKey class")\n    return {\n        **_sample_key_value(attempt_key.sample_key),\n        "attempt_index": attempt_key.attempt_index,\n    }\n\n\n@dataclass(frozen=True, slots=True, init=False)\nclass AttemptCompletionEnvelope:\n    """Topology-independent semantic completion commitment."""\n\n    attempt_key: AttemptKey\n    generation_namespace_digest: str\n    attempt_input_commitment_digest: str\n    completion_status: CompletionStatus\n    completion_digest: str\n    search_branch_digest: str\n    choice_ledger_digest: str\n    identity_ledger_digest: str\n    schema_version: str = ATTEMPT_COMPLETION_ENVELOPE_SCHEMA_VERSION\n\n    def __post_init__(self) -> None:\n        if type(self) is not AttemptCompletionEnvelope:\n            raise PublicationProtocolError("completion envelopes must use the exact class")\n        _attempt_key_value(self.attempt_key)\n        for field_name, value in (\n            ("generation_namespace_digest", self.generation_namespace_digest),\n            ("attempt_input_commitment_digest", self.attempt_input_commitment_digest),\n            ("completion_digest", self.completion_digest),\n            ("search_branch_digest", self.search_branch_digest),\n            ("choice_ledger_digest", self.choice_ledger_digest),\n            ("identity_ledger_digest", self.identity_ledger_digest),\n        ):\n            _require_digest(value, field_name)\n        if type(self.completion_status) is not CompletionStatus:\n            raise PublicationProtocolError("completion_status must use the exact enum")\n        if self.schema_version != ATTEMPT_COMPLETION_ENVELOPE_SCHEMA_VERSION:\n            raise PublicationProtocolError(\n                "completion envelope schema version does not match the v0.4 registry"\n            )\n\n    @classmethod\n    def from_completion(\n        cls,\n        completion: AttemptAccepted | AttemptRejected,\n    ) -> AttemptCompletionEnvelope:\n        if cls is not AttemptCompletionEnvelope:\n            raise PublicationProtocolError("completion construction requires the exact class")\n        if type(completion) is AttemptAccepted:\n            status = CompletionStatus.ACCEPTED\n        elif type(completion) is AttemptRejected:\n            status = CompletionStatus.REJECTED\n        else:\n            raise PublicationProtocolError(\n                "semantic completion must be an exact AttemptAccepted or AttemptRejected"\n            )\n        envelope = object.__new__(AttemptCompletionEnvelope)\n        object.__setattr__(envelope, "attempt_key", completion.attempt_key)\n        object.__setattr__(\n            envelope,\n            "generation_namespace_digest",\n            completion.generation_namespace_digest,\n        )\n        object.__setattr__(\n            envelope,\n            "attempt_input_commitment_digest",\n            completion.attempt_input_commitment_digest,\n        )\n        object.__setattr__(envelope, "completion_status", status)\n        object.__setattr__(envelope, "completion_digest", completion.completion_digest)\n        object.__setattr__(envelope, "search_branch_digest", completion.search_branch_digest)\n        object.__setattr__(envelope, "choice_ledger_digest", completion.choice_ledger_digest)\n        object.__setattr__(envelope, "identity_ledger_digest", completion.identity_ledger_digest)\n        object.__setattr__(\n            envelope,\n            "schema_version",\n            ATTEMPT_COMPLETION_ENVELOPE_SCHEMA_VERSION,\n        )\n        envelope.__post_init__()\n        return envelope\n\n    def validate_completion(self, completion: AttemptAccepted | AttemptRejected) -> None:\n        expected = AttemptCompletionEnvelope.from_completion(completion)\n        if self != expected:\n            raise PublicationProtocolError(\n                "completion envelope does not match the supplied semantic completion"\n            )\n\n    def to_json_value(self) -> dict[str, object]:\n        return {\n            "attempt_input_commitment_digest": self.attempt_input_commitment_digest,\n            "attempt_key": _attempt_key_value(self.attempt_key),\n            "choice_ledger_digest": self.choice_ledger_digest,\n            "completion_digest": self.completion_digest,\n            "completion_status": self.completion_status.value,\n            "generation_namespace_digest": self.generation_namespace_digest,\n            "identity_ledger_digest": self.identity_ledger_digest,\n            "schema_version": self.schema_version,\n            "search_branch_digest": self.search_branch_digest,\n        }\n\n    @property\n    def canonical_bytes(self) -> bytes:\n        return canonical_json_bytes(self.to_json_value())\n\n    @property\n    def digest(self) -> str:\n        return canonical_sha256(self.to_json_value())\n\n\n@dataclass(frozen=True, slots=True, init=False)\nclass InventoryCompletionReference:\n    """Inventory-authorized reference to one topology-independent completion envelope."""\n\n    inventory_digest: str\n    global_ordinal: int\n    sample_key: SampleKey\n    attempt_key: AttemptKey\n    sample_execution_spec_digest: str\n    completion_envelope_digest: str\n    schema_version: str = INVENTORY_COMPLETION_REFERENCE_SCHEMA_VERSION\n\n    def __post_init__(self) -> None:\n        if type(self) is not InventoryCompletionReference:\n            raise PublicationProtocolError("inventory references must use the exact class")\n        _require_digest(self.inventory_digest, "inventory_digest")\n        if type(self.global_ordinal) is not int or not 0 <= self.global_ordinal <= _UINT32_MAX:\n            raise PublicationProtocolError("global_ordinal must be an exact uint32")\n        _sample_key_value(self.sample_key)\n        _attempt_key_value(self.attempt_key)\n        if self.attempt_key.sample_key != self.sample_key:\n            raise PublicationProtocolError("attempt_key and sample_key must identify one sample")\n        _require_digest(self.sample_execution_spec_digest, "sample_execution_spec_digest")\n        _require_digest(self.completion_envelope_digest, "completion_envelope_digest")\n        if self.schema_version != INVENTORY_COMPLETION_REFERENCE_SCHEMA_VERSION:\n            raise PublicationProtocolError(\n                "inventory reference schema version does not match the v0.4 registry"\n            )\n\n    @classmethod\n    def from_inventory(\n        cls,\n        inventory: ExecutionInventory,\n        envelope: AttemptCompletionEnvelope,\n    ) -> InventoryCompletionReference:\n        if cls is not InventoryCompletionReference:\n            raise PublicationProtocolError("inventory reference construction requires exact class")\n        if type(inventory) is not ExecutionInventory:\n            raise PublicationProtocolError("inventory reference requires an exact inventory")\n        if type(envelope) is not AttemptCompletionEnvelope:\n            raise PublicationProtocolError("inventory reference requires an exact envelope")\n        if envelope.generation_namespace_digest != inventory.generation_namespace_digest:\n            raise PublicationProtocolError(\n                "completion namespace does not match the execution inventory"\n            )\n        matching = tuple(\n            spec for spec in inventory.samples if spec.sample_key == envelope.attempt_key.sample_key\n        )\n        if len(matching) != 1:\n            raise PublicationProtocolError("completion sample is absent from the inventory")\n        spec = matching[0]\n        if not spec.attempt_range.contains(envelope.attempt_key.attempt_index):\n            raise PublicationProtocolError(\n                "completion attempt is outside the inventory attempt range"\n            )\n        reference = object.__new__(InventoryCompletionReference)\n        object.__setattr__(reference, "inventory_digest", inventory.digest)\n        object.__setattr__(reference, "global_ordinal", spec.global_ordinal)\n        object.__setattr__(reference, "sample_key", spec.sample_key)\n        object.__setattr__(reference, "attempt_key", envelope.attempt_key)\n        object.__setattr__(reference, "sample_execution_spec_digest", spec.digest)\n        object.__setattr__(reference, "completion_envelope_digest", envelope.digest)\n        object.__setattr__(\n            reference,\n            "schema_version",\n            INVENTORY_COMPLETION_REFERENCE_SCHEMA_VERSION,\n        )\n        reference.__post_init__()\n        return reference\n\n    def validate_against(\n        self,\n        inventory: ExecutionInventory,\n        envelope: AttemptCompletionEnvelope,\n    ) -> None:\n        expected = InventoryCompletionReference.from_inventory(inventory, envelope)\n        if self != expected:\n            raise PublicationProtocolError(\n                "inventory completion reference does not match its authority"\n            )\n\n    def to_json_value(self) -> dict[str, object]:\n        return {\n            "attempt_key": _attempt_key_value(self.attempt_key),\n            "completion_envelope_digest": self.completion_envelope_digest,\n            "global_ordinal": self.global_ordinal,\n            "inventory_digest": self.inventory_digest,\n            "sample_execution_spec_digest": self.sample_execution_spec_digest,\n            "sample_key": _sample_key_value(self.sample_key),\n            "schema_version": self.schema_version,\n        }\n\n    @property\n    def canonical_bytes(self) -> bytes:\n        return canonical_json_bytes(self.to_json_value())\n\n    @property\n    def digest(self) -> str:\n        return canonical_sha256(self.to_json_value())\n\n\n@dataclass(frozen=True, slots=True)\nclass OperationalPublicationReceipt:\n    """Append-only operational receipt that never enters semantic completion identity."""\n\n    execution_run_id: str\n    inventory_digest: str\n    attempt_key: AttemptKey\n    publication_ordinal: int\n    object_kind: PublicationObjectKind\n    object_digest: str\n    disposition: PublicationDisposition\n    previous_publication_receipt_digest: str | None\n    schema_version: str = OPERATIONAL_PUBLICATION_SCHEMA_VERSION\n\n    def __post_init__(self) -> None:\n        if type(self) is not OperationalPublicationReceipt:\n            raise PublicationProtocolError("publication receipts must use the exact class")\n        _require_token(self.execution_run_id, "execution_run_id")\n        _require_digest(self.inventory_digest, "inventory_digest")\n        _attempt_key_value(self.attempt_key)\n        if (\n            type(self.publication_ordinal) is not int\n            or not 0 <= self.publication_ordinal <= _UINT32_MAX\n        ):\n            raise PublicationProtocolError("publication_ordinal must be an exact uint32")\n        if type(self.object_kind) is not PublicationObjectKind:\n            raise PublicationProtocolError("object_kind must use the exact enum")\n        _require_digest(self.object_digest, "object_digest")\n        if type(self.disposition) is not PublicationDisposition:\n            raise PublicationProtocolError("disposition must use the exact enum")\n        if self.publication_ordinal == 0:\n            if self.previous_publication_receipt_digest is not None:\n                raise PublicationProtocolError(\n                    "initial publication receipt cannot reference a predecessor"\n                )\n        else:\n            _require_digest(\n                self.previous_publication_receipt_digest,\n                "previous_publication_receipt_digest",\n            )\n        if self.schema_version != OPERATIONAL_PUBLICATION_SCHEMA_VERSION:\n            raise PublicationProtocolError(\n                "publication receipt schema version does not match the v0.4 registry"\n            )\n\n    @classmethod\n    def append(\n        cls,\n        *,\n        previous: OperationalPublicationReceipt | None,\n        execution_run_id: str,\n        inventory_digest: str,\n        attempt_key: AttemptKey,\n        object_kind: PublicationObjectKind,\n        object_digest: str,\n        disposition: PublicationDisposition,\n    ) -> OperationalPublicationReceipt:\n        if cls is not OperationalPublicationReceipt:\n            raise PublicationProtocolError("publication receipt construction requires exact class")\n        if previous is not None and type(previous) is not OperationalPublicationReceipt:\n            raise PublicationProtocolError("previous receipt must use the exact class")\n        ordinal = 0 if previous is None else previous.publication_ordinal + 1\n        if previous is not None:\n            if previous.execution_run_id != execution_run_id:\n                raise PublicationProtocolError("publication receipt chain spans execution runs")\n            if previous.inventory_digest != inventory_digest:\n                raise PublicationProtocolError("publication receipt chain spans inventories")\n            if previous.attempt_key != attempt_key:\n                raise PublicationProtocolError("publication receipt chain spans attempts")\n        return cls(\n            execution_run_id=execution_run_id,\n            inventory_digest=inventory_digest,\n            attempt_key=attempt_key,\n            publication_ordinal=ordinal,\n            object_kind=object_kind,\n            object_digest=object_digest,\n            disposition=disposition,\n            previous_publication_receipt_digest=(\n                None if previous is None else previous.digest\n            ),\n        )\n\n    def to_json_value(self) -> dict[str, object]:\n        return {\n            "attempt_key": _attempt_key_value(self.attempt_key),\n            "disposition": self.disposition.value,\n            "execution_run_id": self.execution_run_id,\n            "inventory_digest": self.inventory_digest,\n            "object_digest": self.object_digest,\n            "object_kind": self.object_kind.value,\n            "previous_publication_receipt_digest": (\n                self.previous_publication_receipt_digest\n            ),\n            "publication_ordinal": self.publication_ordinal,\n            "schema_version": self.schema_version,\n        }\n\n    @property\n    def canonical_bytes(self) -> bytes:\n        return canonical_json_bytes(self.to_json_value())\n\n    @property\n    def digest(self) -> str:\n        return canonical_sha256(self.to_json_value())\n\n\ndef validate_publication_receipt_chain(\n    receipts: tuple[OperationalPublicationReceipt, ...],\n) -> tuple[OperationalPublicationReceipt, ...]:\n    if type(receipts) is not tuple or not receipts:\n        raise PublicationProtocolError("publication receipt chain requires an immutable tuple")\n    if not all(type(receipt) is OperationalPublicationReceipt for receipt in receipts):\n        raise PublicationProtocolError("publication receipt chain contains a derived value")\n    first = receipts[0]\n    for index, receipt in enumerate(receipts):\n        if receipt.execution_run_id != first.execution_run_id:\n            raise PublicationProtocolError("publication receipt chain spans execution runs")\n        if receipt.inventory_digest != first.inventory_digest:\n            raise PublicationProtocolError("publication receipt chain spans inventories")\n        if receipt.attempt_key != first.attempt_key:\n            raise PublicationProtocolError("publication receipt chain spans attempts")\n        if receipt.publication_ordinal != index:\n            raise PublicationProtocolError(\n                "publication receipt ordinals must be contiguous from zero"\n            )\n        expected_previous = None if index == 0 else receipts[index - 1].digest\n        if receipt.previous_publication_receipt_digest != expected_previous:\n            raise PublicationProtocolError(\n                "publication receipt previous-digest chain is broken"\n            )\n    return receipts\n\n\ndef reference_spec(\n    inventory: ExecutionInventory,\n    reference: InventoryCompletionReference,\n) -> SampleExecutionSpec:\n    """Resolve and verify the unique inventory spec committed by a reference."""\n\n    if type(inventory) is not ExecutionInventory:\n        raise PublicationProtocolError("reference resolution requires an exact inventory")\n    if type(reference) is not InventoryCompletionReference:\n        raise PublicationProtocolError("reference resolution requires an exact reference")\n    if reference.inventory_digest != inventory.digest:\n        raise PublicationProtocolError("reference belongs to a different inventory")\n    matching = tuple(\n        spec\n        for spec in inventory.samples\n        if spec.global_ordinal == reference.global_ordinal\n        and spec.sample_key == reference.sample_key\n    )\n    if len(matching) != 1:\n        raise PublicationProtocolError("reference does not resolve one inventory spec")\n    spec = matching[0]\n    if spec.digest != reference.sample_execution_spec_digest:\n        raise PublicationProtocolError("reference sample-spec digest does not match")\n    if not spec.attempt_range.contains(reference.attempt_key.attempt_index):\n        raise PublicationProtocolError("reference attempt is outside the declared range")\n    return spec\n')

write('src/csd_foundry/synthesis/v0_4/publication_store.py', '"""Atomic content-addressed no-clobber publication storage."""\n\nfrom __future__ import annotations\n\nimport hashlib\nimport os\nimport re\nimport uuid\nfrom collections.abc import Callable\nfrom dataclasses import dataclass\nfrom pathlib import Path\n\nfrom csd_foundry.synthesis.v0_4.publication_protocol import PublicationDisposition\nfrom csd_foundry.synthesis.v0_4.serialization import canonical_json_bytes\n\n_HEX_256_PATTERN = re.compile(r"^[0-9a-f]{64}$")\n\n\nclass PublicationStoreError(RuntimeError):\n    """Base class for publication storage failures."""\n\n\nclass PublicationConflictError(PublicationStoreError):\n    """Raised when an existing digest path contains different bytes."""\n\n\nclass PublicationCorruptionError(PublicationStoreError):\n    """Raised when authoritative bytes do not match their digest path."""\n\n\nclass InjectedPublicationCrash(PublicationStoreError):\n    """Test-only crash injected at a durable publication boundary."""\n\n\nFaultInjector = Callable[[str], None]\n\n\n@dataclass(frozen=True, slots=True)\nclass PublicationResult:\n    digest: str\n    relative_path: str\n    disposition: PublicationDisposition\n\n\n@dataclass(frozen=True, slots=True)\nclass RecoveryReport:\n    temporary_objects_removed: int\n    authoritative_objects_verified: int\n\n\nclass ContentAddressedPublicationStore:\n    """Filesystem store using durable staging and atomic no-clobber installation."""\n\n    def __init__(self, root: Path) -> None:\n        if not isinstance(root, Path):\n            raise PublicationStoreError("publication root must be a pathlib Path")\n        self.root = root\n        self.objects_root = root / "objects"\n        self.temporary_root = root / ".tmp"\n        self.objects_root.mkdir(parents=True, exist_ok=True)\n        self.temporary_root.mkdir(parents=True, exist_ok=True)\n\n    @staticmethod\n    def _require_digest(digest: object) -> str:\n        if type(digest) is not str or _HEX_256_PATTERN.fullmatch(digest) is None:\n            raise PublicationStoreError("object digest must be a lowercase SHA-256 digest")\n        return digest\n\n    def object_path(self, digest: str) -> Path:\n        normalized = self._require_digest(digest)\n        return self.objects_root / normalized[:2] / normalized[2:]\n\n    def relative_object_path(self, digest: str) -> str:\n        return self.object_path(digest).relative_to(self.root).as_posix()\n\n    @staticmethod\n    def _fsync_directory(path: Path) -> None:\n        descriptor = os.open(path, os.O_RDONLY)\n        try:\n            os.fsync(descriptor)\n        finally:\n            os.close(descriptor)\n\n    @staticmethod\n    def _invoke(fault_injector: FaultInjector | None, stage: str) -> None:\n        if fault_injector is not None:\n            fault_injector(stage)\n\n    def _classify_existing(self, final_path: Path, payload: bytes, digest: str) -> PublicationResult:\n        existing = final_path.read_bytes()\n        existing_digest = hashlib.sha256(existing).hexdigest()\n        if existing_digest != digest:\n            raise PublicationCorruptionError(\n                "authoritative object bytes do not match their digest path"\n            )\n        if existing != payload:\n            raise PublicationConflictError(\n                "existing digest path contains different bytes"\n            )\n        return PublicationResult(\n            digest=digest,\n            relative_path=final_path.relative_to(self.root).as_posix(),\n            disposition=PublicationDisposition.EXISTING_IDENTICAL,\n        )\n\n    def publish_bytes(\n        self,\n        payload: bytes,\n        *,\n        expected_digest: str | None = None,\n        fault_injector: FaultInjector | None = None,\n    ) -> PublicationResult:\n        if type(payload) is not bytes:\n            raise PublicationStoreError("publication payload must use the exact bytes type")\n        digest = hashlib.sha256(payload).hexdigest()\n        if expected_digest is not None:\n            self._require_digest(expected_digest)\n            if digest != expected_digest:\n                raise PublicationCorruptionError(\n                    "publication payload does not match the expected digest"\n                )\n        final_path = self.object_path(digest)\n        final_path.parent.mkdir(parents=True, exist_ok=True)\n        if final_path.exists():\n            return self._classify_existing(final_path, payload, digest)\n\n        temporary_path = self.temporary_root / f"{digest}.{uuid.uuid4().hex}.tmp"\n        with temporary_path.open("xb") as handle:\n            self._invoke(fault_injector, "temporary-created")\n            handle.write(payload)\n            handle.flush()\n            self._invoke(fault_injector, "content-written")\n            os.fsync(handle.fileno())\n            self._invoke(fault_injector, "file-synced")\n\n        try:\n            os.link(temporary_path, final_path)\n        except FileExistsError:\n            result = self._classify_existing(final_path, payload, digest)\n            temporary_path.unlink(missing_ok=True)\n            self._fsync_directory(self.temporary_root)\n            return result\n\n        self._fsync_directory(final_path.parent)\n        self._invoke(fault_injector, "object-installed")\n        temporary_path.unlink(missing_ok=True)\n        self._fsync_directory(self.temporary_root)\n        return PublicationResult(\n            digest=digest,\n            relative_path=final_path.relative_to(self.root).as_posix(),\n            disposition=PublicationDisposition.PUBLISHED,\n        )\n\n    def publish_canonical(\n        self,\n        value: object,\n        *,\n        expected_digest: str | None = None,\n        fault_injector: FaultInjector | None = None,\n    ) -> PublicationResult:\n        return self.publish_bytes(\n            canonical_json_bytes(value),\n            expected_digest=expected_digest,\n            fault_injector=fault_injector,\n        )\n\n    def read_verified(self, digest: str) -> bytes:\n        path = self.object_path(digest)\n        if not path.is_file():\n            raise PublicationStoreError("content-addressed object does not exist")\n        payload = path.read_bytes()\n        if hashlib.sha256(payload).hexdigest() != digest:\n            raise PublicationCorruptionError(\n                "authoritative object bytes do not match their digest path"\n            )\n        return payload\n\n    def recover(self) -> RecoveryReport:\n        removed = 0\n        verified = 0\n        for temporary_path in sorted(self.temporary_root.glob("*.tmp")):\n            declared_digest = temporary_path.name.split(".", 1)[0]\n            if _HEX_256_PATTERN.fullmatch(declared_digest) is not None:\n                final_path = self.object_path(declared_digest)\n                if final_path.exists():\n                    self.read_verified(declared_digest)\n                    verified += 1\n            temporary_path.unlink(missing_ok=True)\n            removed += 1\n        if removed:\n            self._fsync_directory(self.temporary_root)\n        return RecoveryReport(\n            temporary_objects_removed=removed,\n            authoritative_objects_verified=verified,\n        )\n')

write('src/csd_foundry/synthesis/v0_4/publication_validation.py', '"""Validation and frozen evidence for v0.4 append-only publication."""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom pathlib import Path\nfrom tempfile import TemporaryDirectory\n\nfrom csd_foundry.synthesis.v0_4.attempts import (\n    AttemptAccepted,\n    AttemptRejected,\n    AttemptRejection,\n)\nfrom csd_foundry.synthesis.v0_4.canonical_values import CanonicalObject\nfrom csd_foundry.synthesis.v0_4.choice_paths import AttemptKey, AttemptRange, SampleKey\nfrom csd_foundry.synthesis.v0_4.contracts import RejectionCause\nfrom csd_foundry.synthesis.v0_4.execution_protocol import (\n    EXECUTION_VALIDATION_POLICY_ID,\n    EXECUTION_VALIDATION_POLICY_VERSION,\n    SAMPLE_KEY_ENCODING_ID,\n    SAMPLE_KEY_ENCODING_VERSION,\n    SHARD_POLICY_ID,\n    SHARD_POLICY_VERSION,\n    ExecutionInventory,\n    OperationalRetryPolicy,\n    RequiredSchemaVersions,\n    SampleExecutionSpec,\n    execution_validation_policy_document,\n    sample_key_encoding_policy_document,\n    shard_policy_document,\n)\nfrom csd_foundry.synthesis.v0_4.generation_namespace import build_generation_namespace\nfrom csd_foundry.synthesis.v0_4.publication_protocol import (\n    AttemptCompletionEnvelope,\n    InventoryCompletionReference,\n    OperationalPublicationReceipt,\n    PublicationDisposition,\n    PublicationObjectKind,\n    validate_publication_receipt_chain,\n)\nfrom csd_foundry.synthesis.v0_4.publication_store import (\n    ContentAddressedPublicationStore,\n    InjectedPublicationCrash,\n    PublicationCorruptionError,\n    PublicationStoreError,\n)\nfrom csd_foundry.synthesis.v0_4.serialization import canonical_sha256\n\n_TARGET_DEFINITION_DIGEST = canonical_sha256({"target": "publication-v1-known-answer"})\n_ROOT_SEED_COMMITMENT = canonical_sha256({"root_seed": "publication-v1-known-answer"})\n\n\n@dataclass(frozen=True, slots=True)\nclass PublicationValidationReport:\n    release: str\n    vectors_passed: int\n    vector_count: int\n    vector_catalog_digest: str\n    semantic_envelope_topology_independent: bool\n    inventory_reference_authoritative: bool\n    publication_receipts_operational: bool\n    no_clobber_enforced: bool\n    duplicate_publication_idempotent: bool\n    corrupted_existing_rejected: bool\n    crash_debris_recoverable: bool\n    errors: tuple[str, ...]\n\n    @property\n    def success(self) -> bool:\n        return not self.errors\n\n    def to_dict(self) -> dict[str, object]:\n        return {\n            "claim_boundary": (\n                "This report validates topology-independent semantic completion envelopes, "\n                "inventory-authorized completion references, append-only operational "\n                "publication receipts, content-addressed no-clobber object installation, "\n                "duplicate idempotence, corruption rejection, and recovery of temporary "\n                "publication debris. It does not establish shard indexes, manifests, seals, "\n                "streaming reconciliation, canonical corpus merge, planner completeness, "\n                "oracle validity, infeasibility, or release-scale output."\n            ),\n            "corrupted_existing_rejected": self.corrupted_existing_rejected,\n            "crash_debris_recoverable": self.crash_debris_recoverable,\n            "duplicate_publication_idempotent": self.duplicate_publication_idempotent,\n            "errors": list(self.errors),\n            "inventory_reference_authoritative": self.inventory_reference_authoritative,\n            "no_clobber_enforced": self.no_clobber_enforced,\n            "publication_receipts_operational": self.publication_receipts_operational,\n            "release": self.release,\n            "release_scale_claimed": False,\n            "semantic_envelope_topology_independent": (\n                self.semantic_envelope_topology_independent\n            ),\n            "status": "valid" if self.success else "invalid",\n            "vector_catalog_digest": self.vector_catalog_digest,\n            "vector_count": self.vector_count,\n            "vector_evidence_version": 1,\n            "vectors_passed": self.vectors_passed,\n        }\n\n\ndef _producer_digest() -> str:\n    return canonical_sha256({"producer_contract_id": "publication-fixture", "version": 1})\n\n\ndef _sample_spec() -> SampleExecutionSpec:\n    return SampleExecutionSpec(\n        global_ordinal=0,\n        sample_key=SampleKey("v0.4", "publication-v1", 0),\n        attempt_range=AttemptRange(3),\n        producer_contract_id="publication-fixture",\n        producer_contract_version=1,\n        producer_contract_digest=_producer_digest(),\n    )\n\n\ndef publication_fixture_inventory() -> ExecutionInventory:\n    retry_policy = OperationalRetryPolicy(2)\n    return ExecutionInventory(\n        release="v0.4",\n        generation_namespace=build_generation_namespace(_TARGET_DEFINITION_DIGEST),\n        root_seed_commitment=_ROOT_SEED_COMMITMENT,\n        sample_key_encoding_id=SAMPLE_KEY_ENCODING_ID,\n        sample_key_encoding_version=SAMPLE_KEY_ENCODING_VERSION,\n        sample_key_encoding_policy_digest=canonical_sha256(\n            sample_key_encoding_policy_document()\n        ),\n        shard_policy_id=SHARD_POLICY_ID,\n        shard_policy_version=SHARD_POLICY_VERSION,\n        shard_policy_digest=canonical_sha256(shard_policy_document()),\n        shard_count=7,\n        operational_retry_policy_digest=retry_policy.digest,\n        validation_policy_id=EXECUTION_VALIDATION_POLICY_ID,\n        validation_policy_version=EXECUTION_VALIDATION_POLICY_VERSION,\n        validation_policy_digest=canonical_sha256(\n            execution_validation_policy_document()\n        ),\n        required_schema_versions=RequiredSchemaVersions(),\n        samples=(_sample_spec(),),\n    )\n\n\ndef _attempt_key(index: int = 1) -> AttemptKey:\n    return AttemptKey(_sample_spec().sample_key, index)\n\n\ndef publication_fixture_accepted() -> AttemptAccepted:\n    attempt = _attempt_key()\n    return AttemptAccepted(\n        attempt_key=attempt,\n        generation_namespace_digest=publication_fixture_inventory().generation_namespace_digest,\n        attempt_input_commitment_digest=canonical_sha256(\n            {"attempt": attempt.attempt_index, "input": "publication-v1"}\n        ),\n        search_branch_digest=canonical_sha256(\n            {"attempt": attempt.attempt_index, "branch": "accepted"}\n        ),\n        choice_ledger_digest=canonical_sha256(\n            {"attempt": attempt.attempt_index, "choices": "publication-v1"}\n        ),\n        identity_ledger_digest=canonical_sha256(\n            {"attempt": attempt.attempt_index, "identities": "publication-v1"}\n        ),\n        result=CanonicalObject.from_pairs(\n            (("accepted", True), ("fixture", "publication-v1"))\n        ),\n    )\n\n\ndef publication_fixture_rejected() -> AttemptRejected:\n    attempt = AttemptKey(_sample_spec().sample_key, 0)\n    search_branch_digest = canonical_sha256(\n        {"attempt": attempt.attempt_index, "branch": "rejected"}\n    )\n    return AttemptRejected(\n        attempt_key=attempt,\n        generation_namespace_digest=publication_fixture_inventory().generation_namespace_digest,\n        attempt_input_commitment_digest=canonical_sha256(\n            {"attempt": attempt.attempt_index, "input": "publication-v1"}\n        ),\n        search_branch_digest=search_branch_digest,\n        choice_ledger_digest=canonical_sha256(\n            {"attempt": attempt.attempt_index, "choices": "publication-v1"}\n        ),\n        identity_ledger_digest=canonical_sha256(\n            {"attempt": attempt.attempt_index, "identities": "publication-v1"}\n        ),\n        rejection=AttemptRejection(\n            cause=RejectionCause.PLAN_CONSTRUCTION_FAILURE,\n            detail_code="publication-fixture-rejected",\n            constraint_ids=("PUBLICATION.CONSTRAINT.A",),\n            normalized_facts=CanonicalObject.from_pairs(\n                (("attempt_index", attempt.attempt_index), ("fixture", "publication-v1"))\n            ),\n            search_branch_digest=search_branch_digest,\n        ),\n    )\n\n\ndef generate_publication_protocol_digests() -> dict[str, str]:\n    inventory = publication_fixture_inventory()\n    accepted = AttemptCompletionEnvelope.from_completion(publication_fixture_accepted())\n    rejected = AttemptCompletionEnvelope.from_completion(publication_fixture_rejected())\n    reference = InventoryCompletionReference.from_inventory(inventory, accepted)\n    first_receipt = OperationalPublicationReceipt.append(\n        previous=None,\n        execution_run_id="run-publication-v1",\n        inventory_digest=inventory.digest,\n        attempt_key=accepted.attempt_key,\n        object_kind=PublicationObjectKind.ATTEMPT_COMPLETION_ENVELOPE,\n        object_digest=accepted.digest,\n        disposition=PublicationDisposition.PUBLISHED,\n    )\n    second_receipt = OperationalPublicationReceipt.append(\n        previous=first_receipt,\n        execution_run_id="run-publication-v1",\n        inventory_digest=inventory.digest,\n        attempt_key=accepted.attempt_key,\n        object_kind=PublicationObjectKind.INVENTORY_COMPLETION_REFERENCE,\n        object_digest=reference.digest,\n        disposition=PublicationDisposition.EXISTING_IDENTICAL,\n    )\n    return {\n        "accepted-completion-envelope": accepted.digest,\n        "inventory-completion-reference": reference.digest,\n        "no-clobber-layout": canonical_sha256(\n            {\n                "digest": accepted.digest,\n                "relative_path": f"objects/{accepted.digest[:2]}/{accepted.digest[2:]}",\n            }\n        ),\n        "publication-receipt-chain": canonical_sha256(\n            [first_receipt.digest, second_receipt.digest]\n        ),\n        "rejected-completion-envelope": rejected.digest,\n    }\n\n\ndef _validate_store() -> tuple[bool, bool, bool, bool]:\n    accepted = AttemptCompletionEnvelope.from_completion(publication_fixture_accepted())\n    with TemporaryDirectory() as directory:\n        store = ContentAddressedPublicationStore(Path(directory))\n        first = store.publish_bytes(\n            accepted.canonical_bytes,\n            expected_digest=accepted.digest,\n        )\n        second = store.publish_bytes(\n            accepted.canonical_bytes,\n            expected_digest=accepted.digest,\n        )\n        no_clobber = (\n            first.disposition is PublicationDisposition.PUBLISHED\n            and store.read_verified(accepted.digest) == accepted.canonical_bytes\n        )\n        duplicate = second.disposition is PublicationDisposition.EXISTING_IDENTICAL\n\n    with TemporaryDirectory() as directory:\n        store = ContentAddressedPublicationStore(Path(directory))\n        corrupt_path = store.object_path(accepted.digest)\n        corrupt_path.parent.mkdir(parents=True, exist_ok=True)\n        corrupt_path.write_bytes(b"corrupt\\n")\n        try:\n            store.publish_bytes(\n                accepted.canonical_bytes,\n                expected_digest=accepted.digest,\n            )\n        except PublicationCorruptionError:\n            corruption_rejected = True\n        else:\n            corruption_rejected = False\n\n    stages = ("temporary-created", "content-written", "file-synced", "object-installed")\n    recovered = True\n    for stage in stages:\n        with TemporaryDirectory() as directory:\n            store = ContentAddressedPublicationStore(Path(directory))\n\n            def inject(current: str, *, expected: str = stage) -> None:\n                if current == expected:\n                    raise InjectedPublicationCrash(current)\n\n            try:\n                store.publish_bytes(\n                    accepted.canonical_bytes,\n                    expected_digest=accepted.digest,\n                    fault_injector=inject,\n                )\n            except InjectedPublicationCrash:\n                pass\n            report = store.recover()\n            if tuple(store.temporary_root.glob("*.tmp")):\n                recovered = False\n            if stage == "object-installed":\n                try:\n                    store.read_verified(accepted.digest)\n                except PublicationStoreError:\n                    recovered = False\n                if report.authoritative_objects_verified != 1:\n                    recovered = False\n            elif store.object_path(accepted.digest).exists():\n                recovered = False\n    return no_clobber, duplicate, corruption_rejected, recovered\n\n\ndef validate_publication_protocol(release: str) -> PublicationValidationReport:\n    from csd_foundry.synthesis.v0_4.publication_vectors import (\n        EXPECTED_PUBLICATION_DIGESTS,\n        FROZEN_PUBLICATION_VECTOR_CATALOG_DIGEST,\n        PUBLICATION_VECTOR_IDS,\n        validate_publication_vector_catalog,\n    )\n\n    errors: list[str] = []\n    if release != "v0.4":\n        errors.append("publication validation supports only v0.4")\n    try:\n        validate_publication_vector_catalog()\n    except ValueError as exc:\n        errors.append(str(exc))\n    actual = generate_publication_protocol_digests()\n    vectors_passed = sum(\n        actual.get(vector_id) == EXPECTED_PUBLICATION_DIGESTS.get(vector_id)\n        for vector_id in PUBLICATION_VECTOR_IDS\n    )\n    if actual != EXPECTED_PUBLICATION_DIGESTS:\n        errors.append("publication protocol vectors changed")\n\n    inventory = publication_fixture_inventory()\n    completion = publication_fixture_accepted()\n    envelope = AttemptCompletionEnvelope.from_completion(completion)\n    equivalent_envelope = AttemptCompletionEnvelope.from_completion(completion)\n    topology_independent = envelope == equivalent_envelope\n    reference = InventoryCompletionReference.from_inventory(inventory, envelope)\n    try:\n        reference.validate_against(inventory, envelope)\n        inventory_authoritative = True\n    except ValueError:\n        inventory_authoritative = False\n    first_receipt = OperationalPublicationReceipt.append(\n        previous=None,\n        execution_run_id="run-a",\n        inventory_digest=inventory.digest,\n        attempt_key=envelope.attempt_key,\n        object_kind=PublicationObjectKind.ATTEMPT_COMPLETION_ENVELOPE,\n        object_digest=envelope.digest,\n        disposition=PublicationDisposition.PUBLISHED,\n    )\n    second_receipt = OperationalPublicationReceipt.append(\n        previous=first_receipt,\n        execution_run_id="run-a",\n        inventory_digest=inventory.digest,\n        attempt_key=envelope.attempt_key,\n        object_kind=PublicationObjectKind.INVENTORY_COMPLETION_REFERENCE,\n        object_digest=reference.digest,\n        disposition=PublicationDisposition.PUBLISHED,\n    )\n    try:\n        validate_publication_receipt_chain((first_receipt, second_receipt))\n        receipts_operational = (\n            "execution_run_id" not in envelope.to_json_value()\n            and "inventory_digest" not in envelope.to_json_value()\n            and first_receipt.execution_run_id != "run-b"\n        )\n    except ValueError:\n        receipts_operational = False\n\n    no_clobber, duplicate, corruption_rejected, recovered = _validate_store()\n    for condition, message in (\n        (topology_independent, "semantic completion envelope is topology-dependent"),\n        (inventory_authoritative, "inventory reference authority validation failed"),\n        (receipts_operational, "publication receipts leaked into semantic identity"),\n        (no_clobber, "no-clobber publication validation failed"),\n        (duplicate, "duplicate publication was not idempotent"),\n        (corruption_rejected, "corrupted existing object was accepted"),\n        (recovered, "temporary publication debris was not recoverable"),\n    ):\n        if not condition:\n            errors.append(message)\n\n    return PublicationValidationReport(\n        release=release,\n        vectors_passed=vectors_passed,\n        vector_count=len(PUBLICATION_VECTOR_IDS),\n        vector_catalog_digest=FROZEN_PUBLICATION_VECTOR_CATALOG_DIGEST,\n        semantic_envelope_topology_independent=topology_independent,\n        inventory_reference_authoritative=inventory_authoritative,\n        publication_receipts_operational=receipts_operational,\n        no_clobber_enforced=no_clobber,\n        duplicate_publication_idempotent=duplicate,\n        corrupted_existing_rejected=corruption_rejected,\n        crash_debris_recoverable=recovered,\n        errors=tuple(errors),\n    )\n')

write('tests/test_v0_4_publication_protocol.py', 'from __future__ import annotations\n\nfrom dataclasses import replace\nfrom pathlib import Path\n\nimport pytest\n\nfrom csd_foundry.synthesis.v0_4.publication_protocol import (\n    AttemptCompletionEnvelope,\n    InventoryCompletionReference,\n    OperationalPublicationReceipt,\n    PublicationDisposition,\n    PublicationObjectKind,\n    PublicationProtocolError,\n    validate_publication_receipt_chain,\n)\nfrom csd_foundry.synthesis.v0_4.publication_store import (\n    ContentAddressedPublicationStore,\n    InjectedPublicationCrash,\n    PublicationCorruptionError,\n)\nfrom csd_foundry.synthesis.v0_4.publication_validation import (\n    generate_publication_protocol_digests,\n    publication_fixture_accepted,\n    publication_fixture_inventory,\n    publication_fixture_rejected,\n    validate_publication_protocol,\n)\nfrom csd_foundry.synthesis.v0_4.publication_vectors import (\n    EXPECTED_PUBLICATION_DIGESTS,\n    FROZEN_PUBLICATION_VECTOR_CATALOG_DIGEST,\n    publication_vector_catalog_commitment,\n    validate_publication_vector_catalog,\n)\nfrom csd_foundry.synthesis.v0_4.serialization import canonical_sha256\n\n\ndef test_completion_envelope_is_topology_independent() -> None:\n    inventory = publication_fixture_inventory()\n    completion = publication_fixture_accepted()\n    first = AttemptCompletionEnvelope.from_completion(completion)\n    second = AttemptCompletionEnvelope.from_completion(completion)\n    assert first == second\n    assert first.canonical_bytes == second.canonical_bytes\n    assert {\n        "execution_run_id",\n        "inventory_digest",\n        "worker_id",\n        "retry_count",\n        "timestamp",\n        "shard_index",\n        "publication_state",\n    }.isdisjoint(first.to_json_value())\n\n    receipt_a = OperationalPublicationReceipt.append(\n        previous=None,\n        execution_run_id="run-a",\n        inventory_digest=inventory.digest,\n        attempt_key=first.attempt_key,\n        object_kind=PublicationObjectKind.ATTEMPT_COMPLETION_ENVELOPE,\n        object_digest=first.digest,\n        disposition=PublicationDisposition.PUBLISHED,\n    )\n    receipt_b = OperationalPublicationReceipt.append(\n        previous=None,\n        execution_run_id="run-b",\n        inventory_digest=inventory.digest,\n        attempt_key=first.attempt_key,\n        object_kind=PublicationObjectKind.ATTEMPT_COMPLETION_ENVELOPE,\n        object_digest=first.digest,\n        disposition=PublicationDisposition.EXISTING_IDENTICAL,\n    )\n    assert receipt_a.digest != receipt_b.digest\n    assert AttemptCompletionEnvelope.from_completion(completion).digest == first.digest\n\n\ndef test_completion_envelope_accepts_only_semantic_completion_contracts() -> None:\n    accepted = AttemptCompletionEnvelope.from_completion(publication_fixture_accepted())\n    rejected = AttemptCompletionEnvelope.from_completion(publication_fixture_rejected())\n    assert accepted.completion_status.value == "accepted"\n    assert rejected.completion_status.value == "rejected"\n    with pytest.raises(PublicationProtocolError):\n        AttemptCompletionEnvelope.from_completion(object())  # type: ignore[arg-type]\n\n\ndef test_inventory_reference_binds_authority_without_changing_envelope() -> None:\n    inventory = publication_fixture_inventory()\n    envelope = AttemptCompletionEnvelope.from_completion(publication_fixture_accepted())\n    reference = InventoryCompletionReference.from_inventory(inventory, envelope)\n    reference.validate_against(inventory, envelope)\n    assert reference.inventory_digest == inventory.digest\n    assert reference.global_ordinal == 0\n    assert reference.completion_envelope_digest == envelope.digest\n    assert envelope.digest == AttemptCompletionEnvelope.from_completion(\n        publication_fixture_accepted()\n    ).digest\n\n\ndef test_publication_receipts_are_append_only_operational_evidence() -> None:\n    inventory = publication_fixture_inventory()\n    envelope = AttemptCompletionEnvelope.from_completion(publication_fixture_accepted())\n    reference = InventoryCompletionReference.from_inventory(inventory, envelope)\n    first = OperationalPublicationReceipt.append(\n        previous=None,\n        execution_run_id="run-publication",\n        inventory_digest=inventory.digest,\n        attempt_key=envelope.attempt_key,\n        object_kind=PublicationObjectKind.ATTEMPT_COMPLETION_ENVELOPE,\n        object_digest=envelope.digest,\n        disposition=PublicationDisposition.PUBLISHED,\n    )\n    second = OperationalPublicationReceipt.append(\n        previous=first,\n        execution_run_id="run-publication",\n        inventory_digest=inventory.digest,\n        attempt_key=envelope.attempt_key,\n        object_kind=PublicationObjectKind.INVENTORY_COMPLETION_REFERENCE,\n        object_digest=reference.digest,\n        disposition=PublicationDisposition.PUBLISHED,\n    )\n    assert validate_publication_receipt_chain((first, second)) == (first, second)\n    with pytest.raises(PublicationProtocolError):\n        validate_publication_receipt_chain(\n            (\n                first,\n                replace(\n                    second,\n                    previous_publication_receipt_digest=canonical_sha256({"broken": True}),\n                ),\n            )\n        )\n\n\ndef test_content_addressed_store_is_no_clobber_and_idempotent(tmp_path: Path) -> None:\n    envelope = AttemptCompletionEnvelope.from_completion(publication_fixture_accepted())\n    store = ContentAddressedPublicationStore(tmp_path)\n    first = store.publish_bytes(envelope.canonical_bytes, expected_digest=envelope.digest)\n    second = store.publish_bytes(envelope.canonical_bytes, expected_digest=envelope.digest)\n    assert first.disposition is PublicationDisposition.PUBLISHED\n    assert second.disposition is PublicationDisposition.EXISTING_IDENTICAL\n    assert first.relative_path == f"objects/{envelope.digest[:2]}/{envelope.digest[2:]}"\n    assert store.read_verified(envelope.digest) == envelope.canonical_bytes\n\n\ndef test_content_addressed_store_rejects_corrupted_existing_object(tmp_path: Path) -> None:\n    envelope = AttemptCompletionEnvelope.from_completion(publication_fixture_accepted())\n    store = ContentAddressedPublicationStore(tmp_path)\n    path = store.object_path(envelope.digest)\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_bytes(b"corrupt\\n")\n    with pytest.raises(PublicationCorruptionError):\n        store.publish_bytes(envelope.canonical_bytes, expected_digest=envelope.digest)\n\n\n@pytest.mark.parametrize(\n    "stage",\n    ("temporary-created", "content-written", "file-synced", "object-installed"),\n)\ndef test_crash_recovery_never_exposes_partial_authority(tmp_path: Path, stage: str) -> None:\n    envelope = AttemptCompletionEnvelope.from_completion(publication_fixture_accepted())\n    store = ContentAddressedPublicationStore(tmp_path)\n\n    def inject(current: str) -> None:\n        if current == stage:\n            raise InjectedPublicationCrash(current)\n\n    with pytest.raises(InjectedPublicationCrash):\n        store.publish_bytes(\n            envelope.canonical_bytes,\n            expected_digest=envelope.digest,\n            fault_injector=inject,\n        )\n\n    report = store.recover()\n    assert not tuple(store.temporary_root.glob("*.tmp"))\n    if stage == "object-installed":\n        assert store.read_verified(envelope.digest) == envelope.canonical_bytes\n        assert report.authoritative_objects_verified == 1\n    else:\n        assert not store.object_path(envelope.digest).exists()\n\n\ndef test_publication_vectors_and_report_are_frozen() -> None:\n    validate_publication_vector_catalog()\n    assert generate_publication_protocol_digests() == EXPECTED_PUBLICATION_DIGESTS\n    report = validate_publication_protocol("v0.4")\n    assert report.success\n    assert report.vectors_passed == report.vector_count == 5\n    assert report.semantic_envelope_topology_independent\n    assert report.no_clobber_enforced\n    assert report.crash_debris_recoverable\n\n\ndef test_publication_catalog_commitment_covers_expected_values(\n    monkeypatch: pytest.MonkeyPatch,\n) -> None:\n    original = FROZEN_PUBLICATION_VECTOR_CATALOG_DIGEST\n    monkeypatch.setitem(\n        EXPECTED_PUBLICATION_DIGESTS,\n        "accepted-completion-envelope",\n        "0" * 64,\n    )\n    assert canonical_sha256(publication_vector_catalog_commitment()) != original\n    with pytest.raises(ValueError, match="catalog digest changed"):\n        validate_publication_vector_catalog()\n')

write('tests/test_v0_4_publication_artifacts.py', 'from __future__ import annotations\n\nimport json\nfrom pathlib import Path\n\nfrom jsonschema import Draft202012Validator, ValidationError\nimport pytest\n\nfrom csd_foundry.synthesis.v0_4.publication_protocol import (\n    AttemptCompletionEnvelope,\n    InventoryCompletionReference,\n    OperationalPublicationReceipt,\n    PublicationDisposition,\n    PublicationObjectKind,\n)\nfrom csd_foundry.synthesis.v0_4.publication_validation import (\n    publication_fixture_accepted,\n    publication_fixture_inventory,\n    validate_publication_protocol,\n)\nfrom csd_foundry.synthesis.v0_4.publication_vectors import (\n    EXPECTED_PUBLICATION_DIGESTS,\n    FROZEN_PUBLICATION_VECTOR_CATALOG_DIGEST,\n    PUBLICATION_VECTOR_EVIDENCE_VERSION,\n    PUBLICATION_VECTOR_IDS,\n)\n\n_ROOT = Path(__file__).resolve().parents[1]\n\n\ndef _load(path: str) -> object:\n    return json.loads((_ROOT / path).read_text(encoding="utf-8"))\n\n\ndef test_publication_canary_catalog_is_exact() -> None:\n    document = _load("data/canary/v0.4/publication-v1/publication_vectors.json")\n    assert type(document) is dict\n    assert document["evidence_version"] == PUBLICATION_VECTOR_EVIDENCE_VERSION\n    assert document["vector_ids"] == list(PUBLICATION_VECTOR_IDS)\n    assert document["expected_digests"] == EXPECTED_PUBLICATION_DIGESTS\n    assert document["catalog_digest"] == FROZEN_PUBLICATION_VECTOR_CATALOG_DIGEST\n\n\ndef test_publication_report_matches_validator() -> None:\n    assert (\n        _load("reports/publication_protocol_v0.4.json")\n        == validate_publication_protocol("v0.4").to_dict()\n    )\n\n\ndef test_publication_schemas_are_well_formed_and_accept_fixtures() -> None:\n    inventory = publication_fixture_inventory()\n    envelope = AttemptCompletionEnvelope.from_completion(publication_fixture_accepted())\n    reference = InventoryCompletionReference.from_inventory(inventory, envelope)\n    receipt = OperationalPublicationReceipt.append(\n        previous=None,\n        execution_run_id="run-schema",\n        inventory_digest=inventory.digest,\n        attempt_key=envelope.attempt_key,\n        object_kind=PublicationObjectKind.ATTEMPT_COMPLETION_ENVELOPE,\n        object_digest=envelope.digest,\n        disposition=PublicationDisposition.PUBLISHED,\n    )\n    fixtures = (\n        (\n            "specs/v0.4/attempt_completion_envelope.schema.json",\n            envelope.to_json_value(),\n        ),\n        (\n            "specs/v0.4/inventory_completion_reference.schema.json",\n            reference.to_json_value(),\n        ),\n        (\n            "specs/v0.4/operational_publication_receipt.schema.json",\n            receipt.to_json_value(),\n        ),\n    )\n    for path, value in fixtures:\n        schema = _load(path)\n        assert type(schema) is dict\n        Draft202012Validator.check_schema(schema)\n        Draft202012Validator(schema).validate(value)\n\n\ndef test_completion_envelope_schema_rejects_topology_leakage() -> None:\n    envelope = AttemptCompletionEnvelope.from_completion(publication_fixture_accepted())\n    schema = _load("specs/v0.4/attempt_completion_envelope.schema.json")\n    assert type(schema) is dict\n    leaked = {**envelope.to_json_value(), "execution_run_id": "run-leak"}\n    with pytest.raises(ValidationError):\n        Draft202012Validator(schema).validate(leaked)\n\n\ndef test_publication_receipt_schema_enforces_initial_chain_boundary() -> None:\n    inventory = publication_fixture_inventory()\n    envelope = AttemptCompletionEnvelope.from_completion(publication_fixture_accepted())\n    receipt = OperationalPublicationReceipt.append(\n        previous=None,\n        execution_run_id="run-schema",\n        inventory_digest=inventory.digest,\n        attempt_key=envelope.attempt_key,\n        object_kind=PublicationObjectKind.ATTEMPT_COMPLETION_ENVELOPE,\n        object_digest=envelope.digest,\n        disposition=PublicationDisposition.PUBLISHED,\n    )\n    schema = _load("specs/v0.4/operational_publication_receipt.schema.json")\n    assert type(schema) is dict\n    invalid = {\n        **receipt.to_json_value(),\n        "previous_publication_receipt_digest": "0" * 64,\n    }\n    with pytest.raises(ValidationError):\n        Draft202012Validator(schema).validate(invalid)\n')

